export const BULLMQ_QUEUE_SETUP_TEMPLATE = `/**
 * Queue Setup & Connection
 * Centralized queue management
 */

import { Queue, Worker, QueueScheduler, QueueEvents } from 'bullmq';
import Redis from 'ioredis';

// Shared Redis connection
export const createRedisConnection = () => {
    return new Redis({
        host: process.env.REDIS_HOST || 'localhost',
        port: parseInt(process.env.REDIS_PORT || '6379'),
        password: process.env.REDIS_PASSWORD,
        maxRetriesPerRequest: null,
        enableReadyCheck: false,
        retryStrategy: (times: number) => {
            const delay = Math.min(times * 50, 2000);
            console.log(\`[Redis] Retry attempt \${times}, waiting \${delay}ms\`);
            return delay;
        },
    });
};

// Queue registry
const queues: Map<string, Queue> = new Map();
const workers: Map<string, Worker> = new Map();
const schedulers: Map<string, QueueScheduler> = new Map();

/**
 * Get or create a queue instance
 */
export function getQueue(name: string): Queue {
    if (!queues.has(name)) {
        const queue = new Queue(name, {
            connection: createRedisConnection(),
        });
        queues.set(name, queue);
    }
    return queues.get(name)!;
}

/**
 * Register a worker for a queue
 */
export function registerWorker(name: string, worker: Worker): void {
    workers.set(name, worker);
}

/**
 * Graceful shutdown of all queues and workers
 */
export async function shutdownQueues(): Promise<void> {
    console.log('[Queue] Shutting down all queues and workers...');
    
    // Close all workers
    for (const [name, worker] of workers) {
        console.log(\`[Queue] Closing worker: \${name}\`);
        await worker.close();
    }
    
    // Close all schedulers
    for (const [name, scheduler] of schedulers) {
        console.log(\`[Queue] Closing scheduler: \${name}\`);
        await scheduler.close();
    }
    
    // Close all queues
    for (const [name, queue] of queues) {
        console.log(\`[Queue] Closing queue: \${name}\`);
        await queue.close();
    }
    
    console.log('[Queue] All queues shut down successfully');
}

// Handle process signals
process.on('SIGTERM', async () => {
    await shutdownQueues();
    process.exit(0);
});

process.on('SIGINT', async () => {
    await shutdownQueues();
    process.exit(0);
});
`;

