export const RETRY_STRATEGY_TEMPLATE = `/**
 * Custom Retry Strategies
 * Flexible retry logic for different job types
 */

import { BackoffOptions } from 'bullmq';

// ============================================
// Retry Strategy Types
// ============================================

export type RetryStrategyType = 'fixed' | 'exponential' | 'linear' | 'custom';

export interface RetryConfig {
    strategy: RetryStrategyType;
    maxAttempts: number;
    initialDelay: number;
    maxDelay?: number;
    factor?: number;
    customDelays?: number[];
}

// ============================================
// Predefined Retry Strategies
// ============================================

/**
 * Fixed delay retry - same delay between all attempts
 */
export const FIXED_RETRY: RetryConfig = {
    strategy: 'fixed',
    maxAttempts: 3,
    initialDelay: 1000,
};

/**
 * Exponential backoff - delay doubles each attempt
 */
export const EXPONENTIAL_RETRY: RetryConfig = {
    strategy: 'exponential',
    maxAttempts: 5,
    initialDelay: 1000,
    maxDelay: 60000,
    factor: 2,
};

/**
 * Linear backoff - delay increases linearly
 */
export const LINEAR_RETRY: RetryConfig = {
    strategy: 'linear',
    maxAttempts: 5,
    initialDelay: 1000,
    maxDelay: 30000,
    factor: 1.5,
};

/**
 * Fast retry for transient errors
 */
export const FAST_RETRY: RetryConfig = {
    strategy: 'fixed',
    maxAttempts: 3,
    initialDelay: 100,
};

/**
 * Slow retry for rate limiting
 */
export const RATE_LIMIT_RETRY: RetryConfig = {
    strategy: 'exponential',
    maxAttempts: 10,
    initialDelay: 5000,
    maxDelay: 300000,
    factor: 2,
};

// ============================================
// Retry Helper Functions
// ============================================

/**
 * Calculate delay for a given attempt
 */
export function calculateDelay(config: RetryConfig, attempt: number): number {
    const { strategy, initialDelay, maxDelay = Infinity, factor = 2 } = config;
    
    let delay: number;
    
    switch (strategy) {
        case 'fixed':
            delay = initialDelay;
            break;
        case 'exponential':
            delay = initialDelay * Math.pow(factor, attempt - 1);
            break;
        case 'linear':
            delay = initialDelay * attempt * (factor || 1);
            break;
        case 'custom':
            delay = config.customDelays?.[attempt - 1] || initialDelay;
            break;
        default:
            delay = initialDelay;
    }
    
    return Math.min(delay, maxDelay);
}

/**
 * Convert RetryConfig to BullMQ BackoffOptions
 */
export function toBackoffOptions(config: RetryConfig): BackoffOptions {
    switch (config.strategy) {
        case 'exponential':
            return {
                type: 'exponential',
                delay: config.initialDelay,
            };
        case 'fixed':
        default:
            return {
                type: 'fixed',
                delay: config.initialDelay,
            };
    }
}

/**
 * Should retry based on error type
 */
export function shouldRetry(error: Error): boolean {
    // Retry on transient errors
    const retryableErrors = [
        'ECONNREFUSED',
        'ETIMEDOUT',
        'EHOSTUNREACH',
        'ENETUNREACH',
        'ECONNRESET',
        'EPIPE',
    ];
    
    const errorCode = (error as NodeJS.ErrnoException).code;
    if (errorCode && retryableErrors.includes(errorCode)) {
        return true;
    }
    
    // Retry on rate limit errors
    if (error.message.includes('rate limit') || error.message.includes('429')) {
        return true;
    }
    
    // Don't retry on validation errors
    if (error.message.includes('validation') || error.message.includes('invalid')) {
        return false;
    }
    
    return true;
}
`;

