export const DEAD_LETTER_QUEUE_TEMPLATE = `/**
 * Dead Letter Queue (DLQ) Handler
 * Captures and processes failed jobs
 */

import { Queue, Worker, Job } from 'bullmq';
import { createRedisConnection } from './queue-setup';

// Dead Letter Queue name
const DLQ_NAME = '{{DLQ_NAME}}';

// Create DLQ instance
export const deadLetterQueue = new Queue(DLQ_NAME, {
    connection: createRedisConnection(),
    defaultJobOptions: {
        removeOnComplete: false,
        removeOnFail: false,
    },
});

/**
 * Move a failed job to DLQ
 */
export async function moveToDeadLetterQueue(
    originalJob: Job,
    error: Error,
    queueName: string
): Promise<void> {
    await deadLetterQueue.add('failed-job', {
        originalJobId: originalJob.id,
        originalJobName: originalJob.name,
        originalQueueName: queueName,
        originalData: originalJob.data,
        error: {
            message: error.message,
            stack: error.stack,
            name: error.name,
        },
        failedAt: new Date().toISOString(),
        attemptsMade: originalJob.attemptsMade,
    });
    
    console.log(\`[DLQ] Job \${originalJob.id} moved to dead letter queue\`);
}

/**
 * DLQ Worker - processes failed jobs for analysis
 */
export const dlqWorker = new Worker(
    DLQ_NAME,
    async (job) => {
        console.log(\`[DLQ] Analyzing failed job: \${job.data.originalJobId}\`);
        
        // Log failure details
        console.log({
            jobId: job.data.originalJobId,
            queue: job.data.originalQueueName,
            error: job.data.error.message,
            attempts: job.data.attemptsMade,
            failedAt: job.data.failedAt,
        });
        
        // TODO: Implement alerting, metrics, or auto-recovery
        
        return { analyzed: true };
    },
    {
        connection: createRedisConnection(),
        concurrency: 1,
    }
);

/**
 * Get DLQ statistics
 */
export async function getDLQStats(): Promise<{
    total: number;
    byQueue: Record<string, number>;
    byError: Record<string, number>;
}> {
    const jobs = await deadLetterQueue.getJobs(['waiting', 'completed']);
    
    const byQueue: Record<string, number> = {};
    const byError: Record<string, number> = {};
    
    for (const job of jobs) {
        const queue = job.data.originalQueueName;
        const errorMsg = job.data.error?.message || 'Unknown error';
        
        byQueue[queue] = (byQueue[queue] || 0) + 1;
        byError[errorMsg] = (byError[errorMsg] || 0) + 1;
    }
    
    return {
        total: jobs.length,
        byQueue,
        byError,
    };
}

/**
 * Retry a job from DLQ
 */
export async function retryFromDLQ(
    dlqJobId: string,
    getOriginalQueue: (name: string) => Queue
): Promise<boolean> {
    const job = await deadLetterQueue.getJob(dlqJobId);
    if (!job) {
        throw new Error(\`DLQ job \${dlqJobId} not found\`);
    }
    
    const originalQueue = getOriginalQueue(job.data.originalQueueName);
    
    await originalQueue.add(job.data.originalJobName, job.data.originalData);
    await job.remove();
    
    console.log(\`[DLQ] Job \${dlqJobId} retried to \${job.data.originalQueueName}\`);
    return true;
}
`;

