export const JOB_SCHEDULER_TEMPLATE = `/**
 * Job Scheduler
 * Cron-based job scheduling with BullMQ
 */

import { Queue } from 'bullmq';
import { createRedisConnection } from './queue-setup';

// ============================================
// Scheduled Jobs Configuration
// ============================================

export interface ScheduledJobConfig {
    name: string;
    queueName: string;
    pattern: string;  // Cron pattern
    data?: Record<string, unknown>;
    tz?: string;
    description?: string;
}

// Scheduled jobs registry
const scheduledJobs: ScheduledJobConfig[] = [
{{SCHEDULED_JOBS}}
];

// ============================================
// Scheduler Functions
// ============================================

/**
 * Initialize all scheduled jobs
 */
export async function initializeScheduler(
    queues: Map<string, Queue>
): Promise<void> {
    console.log('[Scheduler] Initializing scheduled jobs...');
    
    for (const job of scheduledJobs) {
        const queue = queues.get(job.queueName);
        if (!queue) {
            console.warn(\`[Scheduler] Queue \${job.queueName} not found for job \${job.name}\`);
            continue;
        }
        
        // Add repeatable job
        await queue.add(
            job.name,
            job.data || {},
            {
                repeat: {
                    pattern: job.pattern,
                    tz: job.tz || 'UTC',
                },
            }
        );
        
        console.log(\`[Scheduler] Scheduled job: \${job.name} (\${job.pattern})\`);
    }
    
    console.log(\`[Scheduler] Initialized \${scheduledJobs.length} scheduled jobs\`);
}

/**
 * Remove a scheduled job
 */
export async function removeScheduledJob(
    queue: Queue,
    jobName: string
): Promise<boolean> {
    const repeatableJobs = await queue.getRepeatableJobs();
    const job = repeatableJobs.find(j => j.name === jobName);
    
    if (job) {
        await queue.removeRepeatableByKey(job.key);
        console.log(\`[Scheduler] Removed scheduled job: \${jobName}\`);
        return true;
    }
    
    return false;
}

/**
 * List all scheduled jobs
 */
export async function listScheduledJobs(
    queue: Queue
): Promise<ScheduledJobConfig[]> {
    const repeatableJobs = await queue.getRepeatableJobs();
    
    return repeatableJobs.map(job => ({
        name: job.name || 'unnamed',
        queueName: queue.name,
        pattern: job.pattern || '',
        tz: job.tz,
    }));
}

/**
 * Update scheduled job pattern
 */
export async function updateScheduledJob(
    queue: Queue,
    jobName: string,
    newPattern: string,
    newData?: Record<string, unknown>
): Promise<boolean> {
    // Remove old job
    const removed = await removeScheduledJob(queue, jobName);
    if (!removed) return false;
    
    // Add new job with updated pattern
    await queue.add(
        jobName,
        newData || {},
        {
            repeat: {
                pattern: newPattern,
            },
        }
    );
    
    console.log(\`[Scheduler] Updated job \${jobName} to pattern: \${newPattern}\`);
    return true;
}
`;

