export const QUEUE_MONITORING_TEMPLATE = `/**
 * Queue Monitoring & Metrics
 * Health checks and performance monitoring
 */

import { Queue, QueueEvents } from 'bullmq';
import { createRedisConnection } from './queue-setup';

// ============================================
// Queue Metrics Collection
// ============================================

export interface QueueMetrics {
    queueName: string;
    waiting: number;
    active: number;
    completed: number;
    failed: number;
    delayed: number;
    paused: boolean;
    timestamp: Date;
}

/**
 * Get metrics for a single queue
 */
export async function getQueueMetrics(queue: Queue): Promise<QueueMetrics> {
    const [waiting, active, completed, failed, delayed, paused] = await Promise.all([
        queue.getWaitingCount(),
        queue.getActiveCount(),
        queue.getCompletedCount(),
        queue.getFailedCount(),
        queue.getDelayedCount(),
        queue.isPaused(),
    ]);
    
    return {
        queueName: queue.name,
        waiting,
        active,
        completed,
        failed,
        delayed,
        paused,
        timestamp: new Date(),
    };
}

/**
 * Get metrics for all queues
 */
export async function getAllQueueMetrics(
    queues: Map<string, Queue>
): Promise<QueueMetrics[]> {
    const metrics: QueueMetrics[] = [];
    
    for (const [_, queue] of queues) {
        metrics.push(await getQueueMetrics(queue));
    }
    
    return metrics;
}

// ============================================
// Queue Health Checks
// ============================================

export interface QueueHealthStatus {
    healthy: boolean;
    queueName: string;
    status: 'ok' | 'warning' | 'critical';
    message: string;
    metrics: QueueMetrics;
}

export interface HealthThresholds {
    maxWaiting: number;
    maxFailed: number;
    maxDelayed: number;
}

const DEFAULT_THRESHOLDS: HealthThresholds = {
    maxWaiting: 1000,
    maxFailed: 100,
    maxDelayed: 500,
};

/**
 * Check health of a queue
 */
export async function checkQueueHealth(
    queue: Queue,
    thresholds: HealthThresholds = DEFAULT_THRESHOLDS
): Promise<QueueHealthStatus> {
    const metrics = await getQueueMetrics(queue);
    
    let status: 'ok' | 'warning' | 'critical' = 'ok';
    let message = 'Queue is healthy';
    
    // Check for issues
    if (metrics.failed > thresholds.maxFailed) {
        status = 'critical';
        message = \`High failure rate: \${metrics.failed} failed jobs\`;
    } else if (metrics.waiting > thresholds.maxWaiting) {
        status = 'warning';
        message = \`Queue backlog: \${metrics.waiting} waiting jobs\`;
    } else if (metrics.delayed > thresholds.maxDelayed) {
        status = 'warning';
        message = \`Many delayed jobs: \${metrics.delayed}\`;
    } else if (metrics.paused) {
        status = 'warning';
        message = 'Queue is paused';
    }
    
    return {
        healthy: status !== 'critical',
        queueName: queue.name,
        status,
        message,
        metrics,
    };
}

// ============================================
// Queue Events Listener
// ============================================

/**
 * Create a queue events listener
 */
export function createQueueEventsListener(
    queueName: string,
    handlers: {
        onCompleted?: (jobId: string, result: unknown) => void;
        onFailed?: (jobId: string, error: Error) => void;
        onProgress?: (jobId: string, progress: number) => void;
        onStalled?: (jobId: string) => void;
    }
): QueueEvents {
    const queueEvents = new QueueEvents(queueName, {
        connection: createRedisConnection(),
    });
    
    if (handlers.onCompleted) {
        queueEvents.on('completed', ({ jobId, returnvalue }) => {
            handlers.onCompleted!(jobId, returnvalue);
        });
    }
    
    if (handlers.onFailed) {
        queueEvents.on('failed', ({ jobId, failedReason }) => {
            handlers.onFailed!(jobId, new Error(failedReason));
        });
    }
    
    if (handlers.onProgress) {
        queueEvents.on('progress', ({ jobId, data }) => {
            handlers.onProgress!(jobId, data as number);
        });
    }
    
    if (handlers.onStalled) {
        queueEvents.on('stalled', ({ jobId }) => {
            handlers.onStalled!(jobId);
        });
    }
    
    return queueEvents;
}

// ============================================
// Metrics Exporter (Prometheus-compatible)
// ============================================

/**
 * Export metrics in Prometheus format
 */
export async function exportPrometheusMetrics(
    queues: Map<string, Queue>
): Promise<string> {
    const allMetrics = await getAllQueueMetrics(queues);
    let output = '';
    
    output += '# HELP queue_waiting_jobs Number of jobs waiting in queue\\n';
    output += '# TYPE queue_waiting_jobs gauge\\n';
    for (const m of allMetrics) {
        output += \`queue_waiting_jobs{queue="\${m.queueName}"} \${m.waiting}\\n\`;
    }
    
    output += '# HELP queue_active_jobs Number of active jobs\\n';
    output += '# TYPE queue_active_jobs gauge\\n';
    for (const m of allMetrics) {
        output += \`queue_active_jobs{queue="\${m.queueName}"} \${m.active}\\n\`;
    }
    
    output += '# HELP queue_completed_jobs_total Total completed jobs\\n';
    output += '# TYPE queue_completed_jobs_total counter\\n';
    for (const m of allMetrics) {
        output += \`queue_completed_jobs_total{queue="\${m.queueName}"} \${m.completed}\\n\`;
    }
    
    output += '# HELP queue_failed_jobs_total Total failed jobs\\n';
    output += '# TYPE queue_failed_jobs_total counter\\n';
    for (const m of allMetrics) {
        output += \`queue_failed_jobs_total{queue="\${m.queueName}"} \${m.failed}\\n\`;
    }
    
    return output;
}
`;

