export const RATE_LIMITER_TEMPLATE = `/**
 * Queue Rate Limiting
 * Control job processing rates
 */

import { Queue, Worker } from 'bullmq';

// ============================================
// Rate Limit Configurations
// ============================================

export interface RateLimitConfig {
    max: number;       // Maximum jobs
    duration: number;  // Time window in ms
    groupKey?: string; // Optional grouping key
}

// Predefined rate limits
export const RATE_LIMITS = {
    // Standard limits
    LOW: { max: 10, duration: 1000 },
    NORMAL: { max: 50, duration: 1000 },
    HIGH: { max: 100, duration: 1000 },
    
    // API-friendly limits to avoid rate limiting
    EXTERNAL_API: { max: 5, duration: 1000 },
    EMAIL: { max: 30, duration: 60000 },  // 30 emails per minute
    SMS: { max: 10, duration: 60000 },    // 10 SMS per minute
    
    // Batch processing
    BATCH: { max: 1000, duration: 60000 },
} as const;

/**
 * Create a rate-limited worker
 */
export function createRateLimitedWorker<TData, TResult>(
    queueName: string,
    processor: (job: { data: TData }) => Promise<TResult>,
    rateLimit: RateLimitConfig,
    concurrency: number = 1
): Worker<TData, TResult> {
    return new Worker<TData, TResult>(
        queueName,
        async (job) => processor(job),
        {
            concurrency,
            limiter: {
                max: rateLimit.max,
                duration: rateLimit.duration,
                groupKey: rateLimit.groupKey,
            },
        }
    );
}

/**
 * Dynamic rate limiting based on queue state
 */
export async function adjustRateLimit(
    queue: Queue,
    worker: Worker,
    thresholds: {
        highWaterMark: number;
        lowWaterMark: number;
        highLimit: RateLimitConfig;
        lowLimit: RateLimitConfig;
    }
): Promise<RateLimitConfig> {
    const waitingCount = await queue.getWaitingCount();
    
    if (waitingCount > thresholds.highWaterMark) {
        // Speed up processing
        await worker.rateLimit(thresholds.highLimit.max, thresholds.highLimit.duration);
        console.log(\`[RateLimit] Increased rate for \${queue.name}: \${thresholds.highLimit.max}/\${thresholds.highLimit.duration}ms\`);
        return thresholds.highLimit;
    } else if (waitingCount < thresholds.lowWaterMark) {
        // Slow down processing
        await worker.rateLimit(thresholds.lowLimit.max, thresholds.lowLimit.duration);
        console.log(\`[RateLimit] Decreased rate for \${queue.name}: \${thresholds.lowLimit.max}/\${thresholds.lowLimit.duration}ms\`);
        return thresholds.lowLimit;
    }
    
    return { max: 0, duration: 0 }; // No change
}
`;

